def load() -> pd.DataFrame:
    df = pd.read_csv('data/legal/input/csn-data-book-2024-csv/CSVs/2024_CSN_Number_of_Reports_by_Type.csv', header=0, skiprows=1)
    return df

def process(load_reports_data) -> pd.DataFrame:
    data_2024 = load_reports_data[load_reports_data['Year'] == 2024]['Identity Theft'].values[0]
    data_2001 = load_reports_data[load_reports_data['Year'] == 2001]['Identity Theft'].values[0]

    ratio = data_2024 / data_2001
    ratio_rounded = round(ratio, 4)

    return pd.DataFrame({'Ratio_2024_vs_2001': [ratio_rounded]})
